package com.gymmind.nutrition.application; import com.gymmind.nutrition.domain.model.NutritionFood; public record NutritionFoodView(Long id,Long tenantId,String name,double calories,double protein,double carbohydrate,double fat,String servingSize){public static NutritionFoodView from(NutritionFood f){return new NutritionFoodView(f.getId(),f.getTenantId(),f.getName(),f.getCalories(),f.getProtein(),f.getCarbohydrate(),f.getFat(),f.getServingSize());}}
